import { Injectable, Injector } from '@angular/core';
import { SuperService } from './super.service';
import { VerificacionCredito } from '../models/verificacion.credito.model';
import { firstValueFrom } from 'rxjs';

@Injectable({
  providedIn: 'any'
})
export class VerificacionCreditoService extends SuperService<VerificacionCredito> {
  protected override model: string = "creditos_verificaciones";
  protected override columns: (keyof VerificacionCredito)[] = [
    'credito_id',
    'concepto',
    'revision_datos_ingresados',
    'visita_domicilio',
    'latitud_domicilio',
    'longitud_domicilio',
    'foto_domicilio',
    'llamada_telefonica',
    'autorizado_por',
    'autorizado_fecha',
    'usuario_id'
  ];

  constructor(injector: Injector) {
    super(injector)
  }

  /**
   * switch between aprobado and not aprobado
   * @param {number} id -id verificacion to aprove
   * @returns {Promise<boolean>} true if all good
   */
  async aprobar(id: number): Promise<boolean> {
    const res = await firstValueFrom(this.api.post('api/access/verificaciones/credito', { id }, false))
    return res.status
  }
}
